from collections import deque

class DAGExecutor:
    def __init__(self):
        self.tasks = {}
        self.deps = {}

    def add_node(self, name: str, fn, depends_on: list[str] = None) -> None:
        self.tasks[name] = fn
        self.deps[name] = set(depends_on or [])

    def run(self) -> dict:
        in_deg = {u: len(d) for u, d in self.deps.items()}
        ready = deque([u for u, deg in in_deg.items() if deg == 0])
        results = {}
        while ready:
            node = ready.popleft()
            dep_vals = {d: results[d] for d in self.deps[node]}
            results[node] = self.tasks[node](dep_vals)
            for other, other_deps in self.deps.items():
                if node in other_deps:
                    in_deg[other] -= 1
                    if in_deg[other] == 0:
                        ready.append(other)
        if len(results) != len(self.tasks):
            raise ValueError('Cycle detected in task DAG')
        return results

import math

def warmup_cosine_lr(step: int, warmup_steps: int, total_steps: int, max_lr: float, min_lr: float = 1e-5) -> float:
    if step < warmup_steps:
        return max_lr * (step + 1) / max(1, warmup_steps)
    progress = (step - warmup_steps) / max(1, total_steps - warmup_steps)
    progress = min(1.0, max(0.0, progress))
    return min_lr + 0.5 * (max_lr - min_lr) * (1.0 + math.cos(math.pi * progress))
